package com.acme.shop.checkout;

import java.util.List;

/**
 * Validates that every basket line can be fulfilled from current stock.
 */
public class StockSufficiencyValidator {

    private final StockRepository stock;

    public StockSufficiencyValidator(StockRepository stock) {
        this.stock = stock;
    }

    public void validate(List<BasketLine> lines) {
        for (BasketLine line : lines) {
            int available = stock.availableUnits(line.getSku());
            if (line.getQuantity() > available) {
                throw new InsufficientStockException(
                    "SKU " + line.getSku() + " requested " + line.getQuantity()
                        + " but only " + available + " available");
            }
        }
    }
}

class InsufficientStockException extends RuntimeException {
    public InsufficientStockException(String message) { super(message); }
}

