package com.acme.shop.pricing;

import java.math.BigDecimal;
import java.util.List;

/**
 * Prices an order: line sums, promotion discount, then destination shipping.
 */
public class OrderPricingService {

    private final PromotionEngine promotions;
    private final ShippingRateTable shipping;

    public OrderPricingService(PromotionEngine promotions, ShippingRateTable shipping) {
        this.promotions = promotions;
        this.shipping = shipping;
    }

    public PricedOrder price(List<BasketLine> lines, String country) {
        BigDecimal subtotal = lines.stream()
            .map(l -> l.getUnitPrice().multiply(BigDecimal.valueOf(l.getQuantity())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal discount = promotions.discountFor(lines, subtotal);
        BigDecimal ship = shipping.rateFor(country, subtotal.subtract(discount));
        BigDecimal total = subtotal.subtract(discount).add(ship);
        return new PricedOrder(subtotal, discount, ship, total);
    }
}

