package com.acme.shop.basket;

import java.time.Duration;

/**
 * Adds a line to the basket, reserving stock for a short window.
 */
public class AddToBasketService {

    private static final Duration RESERVATION_WINDOW = Duration.ofMinutes(15);

    private final BasketRepository baskets;
    private final StockReservationService reservations;

    public AddToBasketService(BasketRepository baskets, StockReservationService reservations) {
        this.baskets = baskets;
        this.reservations = reservations;
    }

    public BasketView add(String basketId, String sku, int quantity) {
        reservations.reserve(sku, quantity, RESERVATION_WINDOW);
        Basket b = baskets.require(basketId);
        b.addLine(sku, quantity);
        baskets.save(b);
        return BasketView.from(b);
    }
}

