/** Merges an anonymous basket into a customer's basket after login. */
public class BasketMergeService {
    private final BasketRepository baskets;

    public BasketMergeService(BasketRepository baskets) {
        this.baskets = baskets;
    }

    public BasketView merge(String anonymousId, String customerId) {
        Basket anon = baskets.require(anonymousId);
        Basket target = baskets.require(customerId);
        for (BasketLine line : anon.getLines()) {
