package com.acme.shop.promotions;

import java.time.Instant;
import java.util.List;

/**
 * Applies a customer-entered promotion code at checkout.
 */
public class PromotionCodeApplier {

    private final PromotionRepository promotions;
    private final PromotionEngine engine;

    public PromotionCodeApplier(PromotionRepository promotions, PromotionEngine engine) {
        this.promotions = promotions;
        this.engine = engine;
    }

    public AppliedDiscount apply(String code, List<BasketLine> lines) {
        Promotion promo = promotions.findByCode(code)
            .orElseThrow(() -> new UnknownPromotionException(code));
        if (!promo.isActiveAt(Instant.now())) {
            throw new PromotionExpiredException(code);
        }
        if (!promo.appliesTo(lines)) {
            throw new PromotionNotApplicableException(code);
        }
        return engine.compute(promo, lines);
    }
}

