package com.acme.shop.orders;

import java.time.Duration;
import java.time.Instant;

/**
 * Decision rules for who may cancel an order and when.
 */
public class OrderCancellationPolicy {

    private static final Duration CUSTOMER_WINDOW = Duration.ofMinutes(30);

    public boolean customerMayCancel(Order order, Instant now) {
        if (order.getStatus() != OrderStatus.PLACED) {
            return false;
        }
        return now.isBefore(order.getPlacedAt().plus(CUSTOMER_WINDOW));
    }

    public boolean staffMayCancel(Order order) {
        return order.getStatus() == OrderStatus.PLACED
            || order.getStatus() == OrderStatus.PAID
            || order.getStatus() == OrderStatus.PICKING;
    }

    public void assertCustomerMayCancel(Order order, Instant now) {
        if (!customerMayCancel(order, now)) {
            throw new CancellationNotPermittedException(order.getId());
        }
    }
}

