package com.acme.shop.payments;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an immutable record of every payment attempt.
 */
public class PaymentAttemptRecorder {

    private final EntityManager em;

    public PaymentAttemptRecorder(EntityManager em) {
        this.em = em;
    }

    public void record(String orderId, String providerRef, String outcome, String failureReason) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            PaymentAttempt attempt = new PaymentAttempt();
            attempt.setOrderId(orderId);
            attempt.setProviderRef(providerRef);
            attempt.setOutcome(outcome);
            attempt.setFailureReason(failureReason);
            attempt.setAttemptedAt(Instant.now());
            em.persist(attempt);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

