/* catalog_search.c - substring search across title and description, paginated */
#include <stdio.h>
#include <string.h>
#include "shop_db.h"

int search_products(const char *term, int page, int page_size,
                    product_row_t *out_rows, int max_rows) {
    if (page < 0 || page_size <= 0) return -1;

    db_cursor_t *cur = NULL;
    if (db_open_product_search(&cur, term) != DB_OK) return -1;

    int skip = page * page_size;
    int seen = 0;
    int written = 0;
    product_row_t row;
    while (db_cursor_next(cur, &row) == DB_OK && written < max_rows) {
        if (seen++ < skip) continue;
        out_rows[written++] = row;
    }
    db_close_cursor(cur);

    return written;
}

